<section class="page-hero compact"><div class="container"><span class="eyebrow">Administrator</span><h1>Comment Management</h1><p>Administrators can delete any comment; users can delete only their own comments.</p></div></section>
<section class="section container"><div class="table-wrap panel-table"><table><thead><tr><th>User</th><th>Destination</th><th>Comment</th><th>Date</th><th>Action</th></tr></thead><tbody><?php if(!$comments): ?><tr><td colspan="5" class="empty-cell">No comments found.</td></tr><?php endif; ?><?php foreach($comments as $row): ?><tr><td><strong><?= e($row['user_name']) ?></strong><small class="block muted"><?= e($row['email']) ?></small></td><td><?= e($row['post_title']) ?></td><td><?= e((strlen($row['content'])>180 ? substr($row['content'],0,180).'...' : $row['content'])) ?></td><td><?= e(date('d M Y',strtotime($row['created_at']))) ?></td><td><form method="post" action="<?= e(url('admin/comment/delete')) ?>" onsubmit="return confirm('Delete this comment?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="btn btn-danger btn-sm" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
